// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for challenge and logout detection, classes, dialog-scoped weak phrases
// Flo: each halt kind by url and by text (EN + VI) > weak phrases only in dialogs > classes > normal pages stay clear
// I/O: url + text + dialog samples > expected Halt, Class or null
// Run: zig build test -Dfile=ru-safe-halt-test.zig
// ===================================================================
const std = @import("std"); const halt = @import("ru-safe-halt.zig");
test "checkpoint by url and by text" { try std.testing.expectEqual(halt.Halt.checkpoint, halt.check("https://www.facebook.com/checkpoint/1501092823525282/", "", "").?); try std.testing.expectEqual(halt.Halt.checkpoint, halt.check("https://www.facebook.com/", "Please Confirm Your Identity to continue", "").?); }
test "captcha, 2FA, blocked, warning on page text" { try std.testing.expectEqual(halt.Halt.captcha, halt.check("https://x/y", "Security Check: type the characters you see", "").?); try std.testing.expectEqual(halt.Halt.twofa, halt.check("https://www.facebook.com/two_step_verification/authentication/", "", "").?); try std.testing.expectEqual(halt.Halt.blocked, halt.check("https://x/y", "Action Blocked: you're temporarily blocked", "").?); try std.testing.expectEqual(halt.Halt.warning, halt.check("https://x/y", "We noticed unusual activity on your account", "").?); }
test "weak rate-limit phrases count only inside a dialog" { try std.testing.expect(halt.check("https://x/y", "You're going too fast, please try again later", "") == null); try std.testing.expect(halt.check("https://x/y", "Some post says slow down", "") == null); try std.testing.expectEqual(halt.Halt.ratelimit, halt.check("https://x/y", "", "You're going too fast").?); try std.testing.expectEqual(halt.Halt.ratelimit, halt.check("https://x/y", "", "Bạn thao tác quá nhanh").?); }
test "classes: challenges need you, limits are unsafe" { try std.testing.expectEqual(halt.Class.needs, halt.classOf(.checkpoint)); try std.testing.expectEqual(halt.Class.needs, halt.classOf(.captcha)); try std.testing.expectEqual(halt.Class.needs, halt.classOf(.twofa)); try std.testing.expectEqual(halt.Class.needs, halt.classOf(.logout)); try std.testing.expectEqual(halt.Class.needs, halt.classOf(.overlay)); try std.testing.expectEqual(halt.Class.unsafe, halt.classOf(.warning)); try std.testing.expectEqual(halt.Class.unsafe, halt.classOf(.blocked)); try std.testing.expectEqual(halt.Class.unsafe, halt.classOf(.ratelimit)); }
test "logout by login url or login text" { try std.testing.expectEqual(halt.Halt.logout, halt.check("https://www.facebook.com/login/?next=x", "", "").?); try std.testing.expectEqual(halt.Halt.logout, halt.check("https://www.facebook.com/", "Log in to Facebook", "").?); try std.testing.expect(halt.isLogout(.logout)); try std.testing.expect(!halt.isLogout(.captcha)); }
test "Vietnamese phrases are caught" { try std.testing.expectEqual(halt.Halt.checkpoint, halt.check("https://x/y", "Xác nhận danh tính của bạn", "").?); try std.testing.expectEqual(halt.Halt.blocked, halt.check("https://x/y", "Bạn tạm thời bị chặn tính năng này", "").?); try std.testing.expectEqual(halt.Halt.logout, halt.check("https://x/y", "Đăng nhập Facebook", "").?); }
test "normal pages are clear, only the first 6000 bytes are scanned" { try std.testing.expect(halt.check("https://www.facebook.com/marketplace/you/selling", "Your listings: Red bike, Blue desk. Mark as sold.", "") == null); const allo = std.testing.allocator; const big = try allo.alloc(u8, 7000); defer allo.free(big); @memset(big, 'a'); @memcpy(big[6500..6521], "confirm your identity"); try std.testing.expect(halt.check("https://x/y", big, "") == null); }
test "kind names for logs" { try std.testing.expectEqualStrings("captcha", halt.name(.captcha)); }
